import { db } from "@/lib/db";
import { isSafeCoverVariantFile, isSafePageId, readCoverThumbnail } from "@/lib/cover-store";

/** Serves a versioned low-quality cover preview generated by Hallery itself. */
export async function GET(request: Request, ctx: RouteContext<"/api/covers/[pageId]/thumbnail">) {
  const { pageId } = await ctx.params;
  if (!isSafePageId(pageId)) return new Response("Not found", { status: 404 });

  const requestedFile = new URL(request.url).searchParams.get("f");
  const cached = requestedFile ? null : await db.pageImageCache.findUnique({ where: { notionPageId: pageId } });
  const filename = requestedFile ?? cached?.thumbnailFile;
  if (!filename || !isSafeCoverVariantFile(pageId, filename, ".thumbnail.webp")) {
    return new Response("Not found", { status: 404 });
  }

  const bytes = await readCoverThumbnail(filename);
  if (!bytes) return new Response("Not found", { status: 404 });

  return new Response(new Uint8Array(bytes), {
    headers: {
      "Content-Type": "image/webp",
      // The preview URL carries `checkedAt`, so a replacement receives a new URL.
      "Cache-Control": "public, max-age=31536000, immutable",
    },
  });
}
